<?php
require_once __DIR__ . '/includes/bootstrap.php';require_login('kegiatan');
$pdo=db();$q=trim((string)($_GET['q']??''));$status=trim((string)($_GET['status']??''));$where=[];$params=[];
if($q!==''){$where[]="(k.nama_kegiatan LIKE ? OR k.lokasi LIKE ?)";$params[]="%$q%";$params[]="%$q%";}
if($status!==''){$where[]="k.status=?";$params[]=$status;}
$sql="SELECT k.*,COUNT(kp.id_anggota) jumlah_peserta FROM kegiatan k LEFT JOIN kegiatan_peserta kp ON kp.id_kegiatan=k.id_kegiatan".($where?' WHERE '.implode(' AND ',$where):'')." GROUP BY k.id_kegiatan ORDER BY k.tanggal_mulai DESC";
$st=$pdo->prepare($sql);$st->execute($params);$events=$st->fetchAll();
$pageTitle='Kegiatan';$activeMenu='kegiatan';include __DIR__.'/includes/header.php';
?>
<div class="page-heading"><div><span class="eyebrow">PROGRAM ORGANISASI</span><h1>Manajemen Kegiatan</h1><p>Catat rencana, pelaksanaan, peserta, dan evaluasi kegiatan organisasi.</p></div><a class="btn btn-primary" href="<?= e(url('kegiatan_form.php')) ?>">＋ Tambah Kegiatan</a></div>
<div class="stats-grid stats-three"><article class="stat-card"><span>Total Kegiatan</span><strong><?= (int)$pdo->query("SELECT COUNT(*) FROM kegiatan")->fetchColumn() ?></strong><small>Seluruh kegiatan tercatat</small></article><article class="stat-card"><span>Direncanakan / Berlangsung</span><strong><?= (int)$pdo->query("SELECT COUNT(*) FROM kegiatan WHERE status IN ('Direncanakan','Berlangsung')")->fetchColumn() ?></strong><small>Kegiatan aktif dalam agenda</small></article><article class="stat-card"><span>Selesai</span><strong><?= (int)$pdo->query("SELECT COUNT(*) FROM kegiatan WHERE status='Selesai'")->fetchColumn() ?></strong><small>Kegiatan yang telah dilaksanakan</small></article></div>
<section class="panel"><form class="filter-bar" method="get"><input class="search-input" type="search" name="q" value="<?= e($q) ?>" placeholder="⌕ Cari nama atau lokasi kegiatan..."><select name="status"><option value="">Semua Status</option><?php foreach(['Direncanakan','Berlangsung','Selesai','Dibatalkan'] as $v): ?><option <?= $status===$v?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select><button class="btn btn-outline">Filter</button><a class="btn btn-ghost" href="<?= e(url('kegiatan.php')) ?>">Reset</a></form>
<div class="table-wrap"><table><thead><tr><th>Nama Kegiatan</th><th>Tanggal</th><th>Lokasi</th><th>Peserta</th><th>Status</th><th>Aksi</th></tr></thead><tbody>
<?php if(!$events): ?><tr><td colspan="6"><div class="empty-state"><strong>Belum ada kegiatan</strong><span>Modul ini disiapkan berdasarkan ruang lingkup proposal. Tambahkan kegiatan untuk mulai mencatat agenda organisasi.</span></div></td></tr><?php else: foreach($events as $ev): ?><tr><td><strong><?= e($ev['nama_kegiatan']) ?></strong><small class="table-sub"><?= e($ev['jenis_kegiatan']) ?></small></td><td><?= e(tanggal_id($ev['tanggal_mulai'])) ?><?= $ev['tanggal_selesai']&&$ev['tanggal_selesai']!==$ev['tanggal_mulai']?' – '.e(tanggal_id($ev['tanggal_selesai'])):'' ?></td><td><?= e($ev['lokasi']?:'-') ?></td><td><?= (int)$ev['jumlah_peserta'] ?></td><td><?= status_badge($ev['status']) ?></td><td><div class="action-links"><a href="<?= e(url('kegiatan_form.php?id='.$ev['id_kegiatan'])) ?>">Detail / Edit</a><form method="post" action="<?= e(url('kegiatan_delete.php')) ?>" onsubmit="return confirm('Hapus kegiatan ini?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$ev['id_kegiatan'] ?>"><button class="link-danger">Hapus</button></form></div></td></tr><?php endforeach; endif; ?>
</tbody></table></div><div class="table-footer"><span><?= count($events) ?> kegiatan ditemukan</span><span class="muted small">Rancangan awal modul kegiatan mengikuti kebutuhan proposal.</span></div></section>
